typedef struct {
    s8 driveId;               /* 0x00: -1 = not present */
    u8 unk1;
    u8 pad2[2];
    u32 driveStat;            /* 0x04: sceAta{Set,Clear,Get}DriveStat */
    u32 unk8;
    u32 timeout;              /* 0x0C */
